var<workgroup> tile_a: array<f32, 64>;
var<workgroup> tile_b: array<f32, 64>;
@compute @workgroup_size(8, 8, 1)
fn main(@builtin(global_invocation_id) gid: vec3<u32>, @builtin(local_invocation_id) lid: vec3<u32>) {
  let row = gid.y; let col = gid.x;
  let slot = lid.y * 8u + lid.x;
  var acc = 0.0;
  for (var base = 0u; base < 3u; base += 8u) {
    tile_a[slot] = 0.0; tile_b[slot] = 0.0;
    if (row < 1u && base + lid.x < 3u) { tile_a[slot] = b0[row * 3u + base + lid.x]; }
    if (col < 7u && base + lid.y < 3u) { tile_b[slot] = b1[(base + lid.y) * 7u + col]; }
    workgroupBarrier();
    for (var t = 0u; t < 8u; t += 1u) { acc += tile_a[lid.y * 8u + t] * tile_b[t * 8u + lid.x]; }
    workgroupBarrier();
  }
  if (row < 1u && col < 7u) { result[row * 7u + col] = acc; }
}

